// GROUP 1 — INPUT SCHEMA VALIDATION
// Rejects malformed requests before any model is called.
// unit_number is carried for traceability only. It is NEVER a predictor.

const REQUIRED_PREDICTORS = [
  'time_in_cycles','operational_setting_1','operational_setting_2',
  'sensor_2','sensor_3','sensor_4','sensor_6','sensor_7','sensor_8',
  'sensor_9','sensor_11','sensor_12','sensor_13','sensor_14',
  'sensor_15','sensor_17','sensor_20','sensor_21'
];

const out = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const errors = [];

  if (body.unit_number === undefined || !Number.isInteger(body.unit_number) || body.unit_number < 1) {
    errors.push('unit_number must be an integer of at least 1');
  }

  for (const field of REQUIRED_PREDICTORS) {
    const value = body[field];
    if (value === undefined || value === null) {
      errors.push(`missing predictor: ${field}`);
    } else if (typeof value !== 'number' || !Number.isFinite(value)) {
      errors.push(`predictor is not a finite number: ${field}`);
    }
  }

  if (body.time_in_cycles !== undefined && body.time_in_cycles < 1) {
    errors.push('time_in_cycles must be at least 1');
  }

  const forbidden = ['rul_uncapped','rul_capped_130'];
  for (const field of forbidden) {
    if (body[field] !== undefined) {
      errors.push(`target leakage: ${field} must not be supplied as an input`);
    }
  }

  out.push({
    json: {
      valid: errors.length === 0,
      validation_errors: errors,
      received_at_utc: new Date().toISOString(),
      payload: body
    }
  });
}

return out;

// GROUP 3 — ATTACH UNCERTAINTY AND EXPLANATION
// The service already returns interval, explanation and rule outcome.
// This node normalises the shape for routing and audit, and makes the
// uncalibrated-interval condition explicit rather than silent.

return $input.all().map((item) => {
  const r = item.json;
  const p = r.prediction ?? {};
  const d = r.decision ?? {};

  return {
    json: {
      request_id: r.request_id,
      created_at_utc: r.created_at_utc,
      unit_number: r.engine?.unit_number ?? null,
      time_in_cycles: r.engine?.time_in_cycles ?? null,

      point_rul: p.point_rul_cycles ?? null,
      lower_bound: p.lower_bound_cycles ?? null,
      upper_bound: p.upper_bound_cycles ?? null,
      interval_width: p.interval_width_cycles ?? null,
      interval_status: p.interval_status ?? 'NOT_CALIBRATED',
      interval_is_calibrated: p.interval_status === 'CALIBRATED',
      confidence_level: p.confidence_level ?? null,

      top_drivers: (r.explanation?.top_drivers ?? []).map((x) => x.feature),
      explanation_status: r.explanation?.status ?? 'UNKNOWN',

      priority: d.priority ?? 'prediction_unavailable',
      proposed_action: d.proposed_action ?? null,
      requires_human_review: d.requires_human_review ?? true,
      uncertainty_flag: d.uncertainty_flag ?? true,
      decision_reasons: d.reasons ?? [],

      data_quality_status: r.data_quality?.status ?? 'unknown',
      data_quality_issues: r.data_quality?.issues ?? [],

      model_name: r.provenance?.model_name ?? null,
      model_sha256: r.provenance?.model_sha256 ?? null,
      policy_version: r.provenance?.policy_version ?? null,
      policy_approval_status: r.provenance?.policy_approval_status ?? null,
      service_version: r.provenance?.service_version ?? null,
      workflow_version: '0.1.0-prototype',
      service_error: r.error ?? null
    }
  };
});

// AUTOMATED BRANCH — no human review required by the rule layer.
// The record still states plainly that no human reviewed it.

return $input.all().map((item) => ({
  json: {
    ...item.json,
    review_route: 'automated',
    reviewer_decision: 'not_required',
    reviewer_identity: null,
    reviewer_reason: 'The rule layer did not trigger human review.',
    human_reviewed: false,
    final_approved_action: item.json.proposed_action,
    review_note: 'SIMULATED SYSTEM — no engineer examined this case.'
  }
}));

// GROUP 4 — RECORD THE REVIEWER DECISION
// Merges the form submission back onto the prediction record.

const upstream = $('5 Attach Uncertainty and Explanation').all();

return $input.all().map((item, index) => {
  const base = upstream[Math.min(index, upstream.length - 1)].json;
  const form = item.json;

  const decision = (form['Decision'] ?? 'accept').toLowerCase();
  const finalAction = form['Final approved action'] ?? base.proposed_action;

  return {
    json: {
      ...base,
      review_route: 'human_review',
      reviewer_decision: decision,
      reviewer_identity: form['Reviewer identifier'] ?? 'unidentified',
      reviewer_reason: form['Reason for decision'] ?? null,
      human_reviewed: true,
      review_is_simulated: true,
      final_approved_action: decision === 'reject' ? 'No action approved.' : finalAction,
      reviewed_at_utc: new Date().toISOString(),
      review_note: 'SIMULATED HUMAN REVIEW — research prototype. This does not evidence review by a qualified maintenance engineer.'
    }
  };
});

// ERROR BRANCH A — INVALID INPUT
// Fails closed. No recommendation is produced from a malformed record.

return $input.all().map((item) => ({
  json: {
    status: 'rejected',
    reason: 'input_schema_validation_failed',
    validation_errors: item.json.validation_errors,
    priority: 'data_quality_review',
    proposed_action: 'No recommendation issued. Correct the input record and resubmit.',
    requires_human_review: true,
    workflow_version: '0.1.0-prototype',
    received_at_utc: item.json.received_at_utc
  }
}));

// ERROR BRANCH B — PREDICTION SERVICE FAILURE
// Fails closed. An unavailable model must never silently become
// 'routine monitoring'.

return $input.all().map((item) => ({
  json: {
    status: 'service_failure',
    reason: 'prediction_service_unreachable_or_errored',
    error_detail: item.json.error ?? item.error?.message ?? 'unknown',
    priority: 'prediction_unavailable',
    proposed_action: 'Escalate to an engineer. No automated recommendation is available.',
    requires_human_review: true,
    uncertainty_flag: true,
    workflow_version: '0.1.0-prototype',
    failed_at_utc: new Date().toISOString()
  }
}));
